"""Run the real NetX/ThreadX transport test through a loopback Mosquitto broker."""
import os
import pathlib
import socket
import subprocess
import sys
import tempfile
import time


def main():
    with socket.socket() as listener:
        listener.bind(("127.0.0.1", 0))
        port = listener.getsockname()[1]
    with tempfile.TemporaryDirectory(prefix="uprotocol-broker-", dir=os.getcwd()) as directory:
        config = pathlib.Path(directory) / "mosquitto.conf"
        config.write_text(f"listener {port} 127.0.0.1\nallow_anonymous true\npersistence false\n")
        with (pathlib.Path(directory) / "broker.log").open("w+") as log:
            broker = subprocess.Popen([sys.argv[1], "-c", str(config), "-v"], stdout=log, stderr=log)
            try:
                for _ in range(100):
                    if broker.poll() is not None:
                        raise RuntimeError("Mosquitto exited during startup")
                    try:
                        with socket.create_connection(("127.0.0.1", port), timeout=0.1):
                            break
                    except OSError:
                        time.sleep(0.02)
                else:
                    raise RuntimeError("Mosquitto did not start")
                result = subprocess.run([sys.argv[2]], env={**os.environ, "NETX_UPROTOCOL_BROKER_PORT": str(port)}, timeout=30)
                if result.returncode:
                    log.seek(0)
                    print(log.read())
                return result.returncode
            finally:
                broker.terminate()
                try:
                    broker.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    broker.kill()
                    broker.wait()


if __name__ == "__main__":
    sys.exit(main())
